  1→import { useState } from "react";
  2→import { useQuery, useQueryClient } from "@tanstack/react-query";
  3→import { supabase } from "@/integrations/supabase/client";
  4→import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
  5→import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
  6→import { Button } from "@/components/ui/button";
  7→import { Input } from "@/components/ui/input";
  8→import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
  9→import { Label } from "@/components/ui/label";
 10→import { toast } from "sonner";
 11→import { Pencil, Search, Download, ShieldBan, ShieldCheck, Eye, ChevronLeft, ChevronRight, Loader2, Gift } from "lucide-react";
 12→import { Badge } from "@/components/ui/badge";
 13→import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
 14→import { Sheet, SheetContent, SheetHeader, SheetTitle } from "@/components/ui/sheet";
 15→import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
 16→import { ScrollArea } from "@/components/ui/scroll-area";
 17→import ConfirmDialog from "./ConfirmDialog";
 18→import { logAuditAction } from "@/lib/auditLog";
 19→
 20→interface UserRow {
 21→  id: string;
 22→  email: string;
 23→  credits: number;
 24→  subscription_credits: number;
 25→  topup_credits: number;
 26→  bonus_credits: number;
 27→  plan: string;
 28→  role: string;
 29→  created_at: string;
 30→  last_sign_in_at: string | null;
 31→  banned_until: string | null;
 32→}
 33→
 34→interface UserActivity {
 35→  usage_logs: { id: string; credits_used: number; created_at: string; job_id: string | null }[];
 36→  jobs: { id: string; title: string | null; status: string; created_at: string }[];
 37→  resumes: { id: string; filename: string; status: string; created_at: string }[];
 38→  payments: { id: string; amount: number; currency: string; status: string; credits_purchased: number; created_at: string }[];
 39→}
 40→
 41→const PAGE_SIZE = 25;
 42→
 43→const UsersTab = () => {
 44→  const qc = useQueryClient();
 45→  const [editUser, setEditUser] = useState<UserRow | null>(null);
 46→  const [credits, setCredits] = useState("");
 47→  const [bonusCredits, setBonusCredits] = useState("");
 48→  const [subscriptionCredits, setSubscriptionCredits] = useState("");
 49→  const [topupCredits, setTopupCredits] = useState("");
 50→  const [plan, setPlan] = useState("");
 51→  const [search, setSearch] = useState("");
 52→  const [roleFilter, setRoleFilter] = useState<string>("all");
 53→  const [planFilter, setPlanFilter] = useState<string>("all");
 54→  const [activityUser, setActivityUser] = useState<UserRow | null>(null);
 55→  const [page, setPage] = useState(0);
 56→  const [saving, setSaving] = useState(false);
 57→  const [banTarget, setBanTarget] = useState<UserRow | null>(null);
 58→
 59→  const { data: users, isLoading } = useQuery({
 60→    queryKey: ["admin_users"],
 61→    queryFn: async () => {
 62→      const { data, error } = await supabase.functions.invoke("admin-users", { method: "GET" });
 63→      if (error) throw error;
 64→      if (!Array.isArray(data)) {
 65→        if (data?.error) throw new Error(data.error);
 66→        throw new Error("Unexpected response from admin-users");
 67→      }
 68→      return data as UserRow[];
 69→    },
 70→  });
 71→
 72→  const { data: plans } = useQuery({
 73→    queryKey: ["admin_plans"],
 74→    queryFn: async () => {
 75→      const { data, error } = await supabase.from("plans").select("name").order("name");
 76→      if (error) throw error;
 77→      return data;
 78→    },
 79→  });
 80→
 81→  const { data: activity, isLoading: activityLoading } = useQuery({
 82→    queryKey: ["admin_user_activity", activityUser?.id],
 83→    enabled: !!activityUser,
 84→    queryFn: async () => {
 85→      const { data, error } = await supabase.functions.invoke("admin-users", {
 86→        body: { action: "activity", user_id: activityUser!.id },
 87→      });
 88→      if (error) throw error;
 89→      return data as UserActivity;
 90→    },
 91→  });
 92→
 93→  const filtered = users?.filter((u) => {
 94→    const matchesSearch = !search || u.email.toLowerCase().includes(search.toLowerCase());
 95→    const matchesRole = roleFilter === "all" || u.role === roleFilter;
 96→    const matchesPlan = planFilter === "all" || u.plan === planFilter;
 97→    return matchesSearch && matchesRole && matchesPlan;
 98→  }) ?? [];
 99→
100→  const totalPages = Math.ceil(filtered.length / PAGE_SIZE);
101→  const paged = filtered.slice(page * PAGE_SIZE, (page + 1) * PAGE_SIZE);
102→
103→  // Reset page when filters change
104→  const updateSearch = (v: string) => { setSearch(v); setPage(0); };
105→  const updateRoleFilter = (v: string) => { setRoleFilter(v); setPage(0); };
106→  const updatePlanFilter = (v: string) => { setPlanFilter(v); setPage(0); };
107→
108→  const openEdit = (u: UserRow) => {
109→    setEditUser(u);
110→    setCredits(String(u.credits));
111→    setSubscriptionCredits(String(u.subscription_credits));
112→    setTopupCredits(String(u.topup_credits));
113→    setBonusCredits(String(u.bonus_credits));
114→    setPlan(u.plan);
115→  };
116→
117→  const save = async () => {
118→    if (!editUser) return;
119→    setSaving(true);
120→    try {
121→      const { error } = await supabase.functions.invoke("admin-users", {
122→        body: {
123→          user_id: editUser.id,
124→          credits: parseInt(credits),
125→          subscription_credits: parseInt(subscriptionCredits),
126→          topup_credits: parseInt(topupCredits),
127→          bonus_credits: parseInt(bonusCredits),
128→          plan,
129→        },
130→      });
131→      if (error) { toast.error("Failed to update user"); return; }
132→      toast.success("User updated");
133→      logAuditAction("user.update", "user", editUser.id, {
134→        email: editUser.email,
135→        credits: parseInt(credits),
136→        subscription_credits: parseInt(subscriptionCredits),
137→        topup_credits: parseInt(topupCredits),
138→        bonus_credits: parseInt(bonusCredits),
139→        plan,
140→      });
141→      qc.invalidateQueries({ queryKey: ["admin_users"] });
142→      setEditUser(null);
143→    } finally {
144→      setSaving(false);
145→    }
146→  };
147→
148→  const confirmBan = async () => {
149→    if (!banTarget) return;
150→    const isBanned = banTarget.banned_until && new Date(banTarget.banned_until) > new Date();
151→    const { error } = await supabase.functions.invoke("admin-users", {
152→      body: { action: "ban", user_id: banTarget.id, banned: !isBanned },
153→    });
154→    if (error) { toast.error("Failed to update ban status"); return; }
155→    toast.success(isBanned ? "User unbanned" : "User banned");
156→    logAuditAction(isBanned ? "user.unban" : "user.ban", "user", banTarget.id, { email: banTarget.email });
157→    qc.invalidateQueries({ queryKey: ["admin_users"] });
158→    setBanTarget(null);
159→  };
160→
161→  const exportGDPR = async (u: UserRow) => {
162→    toast.info("Exporting user data…");
163→    const { data, error } = await supabase.functions.invoke("admin-users", {
164→      body: { action: "gdpr_export", user_id: u.id },
165→    });
166→    if (error) { toast.error("Export failed"); return; }
167→    const blob = new Blob([JSON.stringify(data, null, 2)], { type: "application/json" });
168→    const url = URL.createObjectURL(blob);
169→    const a = document.createElement("a");
170→    a.href = url;
171→    a.download = `gdpr-export-${u.email}-${new Date().toISOString().slice(0, 10)}.json`;
172→    a.click();
173→    URL.revokeObjectURL(url);
174→    toast.success("GDPR export downloaded");
175→  };
176→
177→  const isBanned = (u: UserRow) => u.banned_until && new Date(u.banned_until) > new Date();
178→  const uniquePlans = [...new Set(users?.map((u) => u.plan) ?? [])];
179→
180→  return (
181→    <>
182→      <Card>
183→        <CardHeader className="pb-3">
184→          <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
185→            <CardTitle className="text-lg">User Management</CardTitle>
186→            <div className="flex items-center gap-2 flex-wrap">
187→              <div className="relative">
188→                <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
189→                <Input placeholder="Search email…" value={search} onChange={(e) => updateSearch(e.target.value)} className="pl-8 w-[200px]" />
190→              </div>
191→              <Select value={roleFilter} onValueChange={updateRoleFilter}>
192→                <SelectTrigger className="w-[120px]"><SelectValue placeholder="Role" /></SelectTrigger>
193→                <SelectContent>
194→                  <SelectItem value="all">All Roles</SelectItem>
195→                  <SelectItem value="admin">Admin</SelectItem>
196→                  <SelectItem value="user">User</SelectItem>
197→                </SelectContent>
198→              </Select>
199→              <Select value={planFilter} onValueChange={updatePlanFilter}>
200→                <SelectTrigger className="w-[120px]"><SelectValue placeholder="Plan" /></SelectTrigger>
201→                <SelectContent>
202→                  <SelectItem value="all">All Plans</SelectItem>
203→                  {uniquePlans.map((p) => <SelectItem key={p} value={p}>{p}</SelectItem>)}
204→                </SelectContent>
205→              </Select>
206→              <Badge variant="outline" className="text-xs">{filtered.length} users</Badge>
207→            </div>
208→          </div>
209→        </CardHeader>
210→        <CardContent className="p-0">
211→          <div className="overflow-x-auto">
212→            <Table>
213→              <TableHeader>
214→                <TableRow>
215→                  <TableHead>Email</TableHead>
216→                  <TableHead>Credits</TableHead>
217→                  <TableHead>Plan</TableHead>
218→                  <TableHead>Role</TableHead>
219→                  <TableHead>Status</TableHead>
220→                  <TableHead>Last Sign In</TableHead>
221→                  <TableHead>Joined</TableHead>
222→                  <TableHead className="text-right">Actions</TableHead>
223→                </TableRow>
224→              </TableHeader>
225→              <TableBody>
226→                {isLoading ? (
227→                  <TableRow><TableCell colSpan={8} className="text-center py-8 text-muted-foreground">Loading…</TableCell></TableRow>
228→                ) : paged.length === 0 ? (
229→                  <TableRow><TableCell colSpan={8} className="text-center py-8 text-muted-foreground">No users found</TableCell></TableRow>
230→                ) : paged.map((u) => (
231→                  <TableRow key={u.id} className={isBanned(u) ? "opacity-60" : ""}>
232→                    <TableCell className="font-medium">{u.email}</TableCell>
233→                    <TableCell>
234→                      <div className="flex items-center gap-1.5">
235→                        <span className="font-medium tabular-nums">{u.subscription_credits + u.topup_credits + u.bonus_credits || u.credits}</span>
236→                        {u.bonus_credits > 0 && (
237→                          <Badge variant="outline" className="text-[11px] px-1 py-0 gap-0.5">
238→                            <Gift className="h-2.5 w-2.5" />{u.bonus_credits}
239→                          </Badge>
240→                        )}
241→                      </div>
242→                    </TableCell>
243→                    <TableCell><Badge variant="secondary">{u.plan}</Badge></TableCell>
244→                    <TableCell><Badge variant={u.role === "admin" ? "default" : "outline"}>{u.role}</Badge></TableCell>
245→                    <TableCell>
246→                      {isBanned(u) ? (
247→                        <Badge variant="destructive">Banned</Badge>
248→                      ) : (
249→                        <Badge variant="outline" className="text-emerald-600 border-emerald-300 dark:text-emerald-400 dark:border-emerald-800">Active</Badge>
250→                      )}
251→                    </TableCell>
252→                    <TableCell className="text-sm text-muted-foreground">
253→                      {u.last_sign_in_at ? new Date(u.last_sign_in_at).toLocaleDateString() : "Never"}
254→                    </TableCell>
255→                    <TableCell className="text-sm">{new Date(u.created_at).toLocaleDateString()}</TableCell>
256→                    <TableCell>
257→                      <div className="flex items-center justify-end gap-1">
258→                        <Button variant="ghost" size="icon" title="View Activity" onClick={() => setActivityUser(u)}>
259→                          <Eye className="h-3.5 w-3.5" />
260→                        </Button>
261→                        <Button variant="ghost" size="icon" title="Edit" onClick={() => openEdit(u)}>
262→                          <Pencil className="h-3.5 w-3.5" />
263→                        </Button>
264→                        <Button variant="ghost" size="icon" title={isBanned(u) ? "Unban" : "Ban"} onClick={() => setBanTarget(u)}>
265→                          {isBanned(u) ? <ShieldCheck className="h-3.5 w-3.5 text-emerald-500" /> : <ShieldBan className="h-3.5 w-3.5 text-destructive" />}
266→                        </Button>
267→                        <Button variant="ghost" size="icon" title="GDPR Export" onClick={() => exportGDPR(u)}>
268→                          <Download className="h-3.5 w-3.5" />
269→                        </Button>
270→                      </div>
271→                    </TableCell>
272→                  </TableRow>
273→                ))}
274→              </TableBody>
275→            </Table>
276→          </div>
277→          {totalPages > 1 && (
278→            <div className="flex items-center justify-between px-4 py-3 border-t border-border">
279→              <span className="text-sm text-muted-foreground">Page {page + 1} of {totalPages}</span>
280→              <div className="flex items-center gap-2">
281→                <Button variant="outline" size="icon" className="h-7 w-7" disabled={page === 0} onClick={() => setPage(p => p - 1)}>
282→                  <ChevronLeft className="h-3.5 w-3.5" />
283→                </Button>
284→                <Button variant="outline" size="icon" className="h-7 w-7" disabled={page >= totalPages - 1} onClick={() => setPage(p => p + 1)}>
285→                  <ChevronRight className="h-3.5 w-3.5" />
286→                </Button>
287→              </div>
288→            </div>
289→          )}
290→        </CardContent>
291→      </Card>
292→
293→      {/* Edit Dialog with Plan dropdown */}
294→      <Dialog open={editUser !== null} onOpenChange={(o) => !o && setEditUser(null)}>
295→        <DialogContent>
296→          <DialogHeader><DialogTitle>Edit User: {editUser?.email}</DialogTitle></DialogHeader>
297→          <div className="space-y-3">
298→            <div className="grid grid-cols-2 gap-3">
299→              <div>
300→                <Label className="text-xs text-muted-foreground">Subscription Credits</Label>
301→                <Input type="number" value={subscriptionCredits} onChange={(e) => setSubscriptionCredits(e.target.value)} />
302→              </div>
303→              <div>
304→                <Label className="text-xs text-muted-foreground">Top-up Credits</Label>
305→                <Input type="number" value={topupCredits} onChange={(e) => setTopupCredits(e.target.value)} />
306→              </div>
307→            </div>
308→            <div className="grid grid-cols-2 gap-3">
309→              <div>
310→                <Label className="flex items-center gap-1.5 text-xs text-muted-foreground">
311→                  <Gift className="h-3 w-3" /> Bonus Credits
312→                </Label>
313→                <Input type="number" value={bonusCredits} onChange={(e) => setBonusCredits(e.target.value)} />
314→              </div>
315→              <div>
316→                <Label className="text-xs text-muted-foreground">Legacy Credits</Label>
317→                <Input type="number" value={credits} onChange={(e) => setCredits(e.target.value)} />
318→              </div>
319→            </div>
320→            <div>
321→              <Label>Plan</Label>
322→              <Select value={plan} onValueChange={setPlan}>
323→                <SelectTrigger><SelectValue placeholder="Select plan" /></SelectTrigger>
324→                <SelectContent>
325→                  <SelectItem value="free">Free</SelectItem>
326→                  {plans?.map((p) => (
327→                    <SelectItem key={p.name} value={p.name}>{p.name}</SelectItem>
328→                  ))}
329→                </SelectContent>
330→              </Select>
331→            </div>
332→            <Button onClick={save} className="w-full" disabled={saving}>
333→              {saving ? <Loader2 className="h-4 w-4 mr-1 animate-spin" /> : null}
334→              Save Changes
335→            </Button>
336→          </div>
337→        </DialogContent>
338→      </Dialog>
339→
340→      {/* Ban Confirmation */}
341→      <ConfirmDialog
342→        open={banTarget !== null}
343→        onOpenChange={(o) => !o && setBanTarget(null)}
344→        title={banTarget && isBanned(banTarget) ? "Unban User" : "Ban User"}
345→        description={
346→          banTarget && isBanned(banTarget)
347→            ? `Are you sure you want to unban ${banTarget?.email}?`
348→            : `Are you sure you want to ban ${banTarget?.email}? They will lose access to the platform.`
349→        }
350→        confirmLabel={banTarget && isBanned(banTarget) ? "Unban" : "Ban User"}
351→        variant={banTarget && isBanned(banTarget) ? "default" : "destructive"}
352→        onConfirm={confirmBan}
353→      />
354→
355→      {/* Activity Drawer */}
356→      <Sheet open={activityUser !== null} onOpenChange={(o) => !o && setActivityUser(null)}>
357→        <SheetContent className="sm:max-w-lg w-full">
358→          <SheetHeader>
359→            <SheetTitle className="text-base">{activityUser?.email}</SheetTitle>
360→          </SheetHeader>
361→          <Tabs defaultValue="jobs" className="mt-4">
362→            <TabsList className="w-full grid grid-cols-4">
363→              <TabsTrigger value="jobs">Jobs</TabsTrigger>
364→              <TabsTrigger value="resumes">Resumes</TabsTrigger>
365→              <TabsTrigger value="usage">Usage</TabsTrigger>
366→              <TabsTrigger value="payments">Payments</TabsTrigger>
367→            </TabsList>
368→            <ScrollArea className="h-[calc(100vh-180px)] mt-3">
369→              <TabsContent value="jobs" className="mt-0">
370→                {activityLoading ? <p className="text-sm text-muted-foreground p-4">Loading…</p> : (
371→                  <div className="space-y-2">
372→                    {activity?.jobs?.length === 0 && <p className="text-sm text-muted-foreground p-4">No jobs</p>}
373→                    {activity?.jobs?.map((j) => (
374→                      <div key={j.id} className="p-3 rounded-lg border text-sm">
375→                        <div className="font-medium">{j.title || "Untitled Job"}</div>
376→                        <div className="flex items-center gap-2 mt-1 text-muted-foreground text-xs">
377→                          <Badge variant="outline" className="text-xs">{j.status}</Badge>
378→                          <span>{new Date(j.created_at).toLocaleDateString()}</span>
379→                        </div>
380→                      </div>
381→                    ))}
382→                  </div>
383→                )}
384→              </TabsContent>
385→              <TabsContent value="resumes" className="mt-0">
386→                {activityLoading ? <p className="text-sm text-muted-foreground p-4">Loading…</p> : (
387→                  <div className="space-y-2">
388→                    {activity?.resumes?.length === 0 && <p className="text-sm text-muted-foreground p-4">No resumes</p>}
389→                    {activity?.resumes?.map((r) => (
390→                      <div key={r.id} className="p-3 rounded-lg border text-sm">
391→                        <div className="font-medium truncate">{r.filename}</div>
392→                        <div className="flex items-center gap-2 mt-1 text-muted-foreground text-xs">
393→                          <Badge variant="outline" className="text-xs">{r.status}</Badge>
394→                          <span>{new Date(r.created_at).toLocaleDateString()}</span>
395→                        </div>
396→                      </div>
397→                    ))}
398→                  </div>
399→                )}
400→              </TabsContent>
401→              <TabsContent value="usage" className="mt-0">
402→                {activityLoading ? <p className="text-sm text-muted-foreground p-4">Loading…</p> : (
403→                  <div className="space-y-2">
404→                    {activity?.usage_logs?.length === 0 && <p className="text-sm text-muted-foreground p-4">No usage</p>}
405→                    {activity?.usage_logs?.map((l) => (
406→                      <div key={l.id} className="p-3 rounded-lg border text-sm flex justify-between">
407→                        <span className="text-muted-foreground">{new Date(l.created_at).toLocaleString()}</span>
408→                        <Badge variant="secondary">{l.credits_used} credits</Badge>
409→                      </div>
410→                    ))}
411→                  </div>
412→                )}
413→              </TabsContent>
414→              <TabsContent value="payments" className="mt-0">
415→                {activityLoading ? <p className="text-sm text-muted-foreground p-4">Loading…</p> : (
416→                  <div className="space-y-2">
417→                    {activity?.payments?.length === 0 && <p className="text-sm text-muted-foreground p-4">No payments</p>}
418→                    {activity?.payments?.map((p) => (
419→                      <div key={p.id} className="p-3 rounded-lg border text-sm flex justify-between items-center">
420→                        <div>
421→                          <div className="font-medium">{p.currency} {(p.amount / 100).toFixed(2)}</div>
422→                          <div className="text-xs text-muted-foreground">{p.credits_purchased} credits · {new Date(p.created_at).toLocaleDateString()}</div>
423→                        </div>
424→                        <Badge variant={p.status === "paid" ? "default" : "outline"}>{p.status}</Badge>
425→                      </div>
426→                    ))}
427→                  </div>
428→                )}
429→              </TabsContent>
430→            </ScrollArea>
431→          </Tabs>
432→        </SheetContent>
433→      </Sheet>
434→    </>
435→  );
436→};
437→
438→export default UsersTab;
