 1→import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
 2→import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
 3→
 4→const corsHeaders = {
 5→  "Access-Control-Allow-Origin": "*",
 6→  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
 7→};
 8→
 9→serve(async (req) => {
10→  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
11→
12→  try {
13→    const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
14→    const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
15→
16→    // Verify caller is admin
17→    const authHeader = req.headers.get("Authorization");
18→    if (!authHeader) throw new Error("No auth");
19→
20→    const token = authHeader.replace("Bearer ", "");
21→    const anonKey = Deno.env.get("SUPABASE_PUBLISHABLE_KEY") || Deno.env.get("SUPABASE_ANON_KEY")!;
22→    const supabaseUser = createClient(SUPABASE_URL, anonKey, {
23→      global: { headers: { Authorization: authHeader } },
24→    });
25→    const { data: claimsData, error: claimsError } = await supabaseUser.auth.getClaims(token);
26→    if (claimsError || !claimsData?.claims) throw new Error("Unauthorized");
27→    const userId = claimsData.claims.sub as string;
28→
29→    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
30→
31→    // Check admin role
32→    const { data: roles } = await supabase.from("user_roles").select("role").eq("user_id", userId);
33→    const isAdmin = roles?.some((r: any) => r.role === "admin");
34→    if (!isAdmin) {
35→      return new Response(JSON.stringify({ error: "Admin access required" }), {
36→        status: 403, headers: { ...corsHeaders, "Content-Type": "application/json" },
37→      });
38→    }
39→
40→    const { email, credits } = await req.json();
41→    if (!email || typeof email !== "string" || email.trim().length === 0) throw new Error("Missing or invalid email");
42→    if (credits === undefined || typeof credits !== "number" || !isFinite(credits)) throw new Error("Missing or invalid credits");
43→
44→    // Find user by email via auth admin
45→    const { data: authUsers } = await supabase.auth.admin.listUsers();
46→    const targetUser = authUsers?.users?.find((u: any) => u.email === email);
47→    if (!targetUser) {
48→      return new Response(JSON.stringify({ error: "User not found" }), {
49→        status: 404, headers: { ...corsHeaders, "Content-Type": "application/json" },
50→      });
51→    }
52→
53→    // Relative credit adjustment
54→    const { data: profile } = await supabase.from("profiles").select("credits").eq("user_id", targetUser.id).single();
55→    if (!profile) {
56→      return new Response(JSON.stringify({ error: "Profile not found" }), {
57→        status: 404, headers: { ...corsHeaders, "Content-Type": "application/json" },
58→      });
59→    }
60→    const oldCredits = profile.credits ?? 0;
61→    const newCredits = Math.max(0, oldCredits + credits);
62→    const { error } = await supabase.from("profiles").update({ credits: newCredits }).eq("user_id", targetUser.id);
63→    if (error) throw error;
64→
65→    // Audit trail for admin credit adjustments
66→    await supabase.from("admin_audit_logs").insert({
67→      admin_user_id: userId,
68→      action: "adjust_credits",
69→      entity_type: "user",
70→      entity_id: targetUser.id,
71→      details: {
72→        email,
73→        credits_delta: credits,
74→        old_credits: oldCredits,
75→        new_credits: newCredits,
76→      },
77→    });
78→
79→    return new Response(JSON.stringify({ success: true }), {
80→      headers: { ...corsHeaders, "Content-Type": "application/json" },
81→    });
82→  } catch (err: unknown) {
83→    return new Response(JSON.stringify({ error: err instanceof Error ? err.message : String(err) }), {
84→      status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" },
85→    });
86→  }
87→});
