 61→serve(async (req) => {
 62→  const corsHeaders = { ...baseCorsHeaders, "Access-Control-Allow-Origin": getAllowedOrigin(req) };
 63→  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
 64→
 65→  const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
 66→  const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
 67→  const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
 68→
 69→  try {
 70→    const { to, template_key, variables } = (await req.json()) as SendEmailRequest;
 71→
 72→    if (!to || !template_key) {
 73→      return new Response(JSON.stringify({ error: "Missing 'to' or 'template_key'" }), {
 74→        status: 400,
 75→        headers: { ...corsHeaders, "Content-Type": "application/json" },
 76→      });
 77→    }
 78→
 79→    // Load platform config for Resend credentials
 80→    const { data: config, error: configError } = await supabase
 81→      .from("platform_config")
 82→      .select("resend_api_key, email_from_address, email_from_name, outbound_email_enabled, email_notify_ranking_complete, email_notify_resume_received")
 83→      .limit(1)
 84→      .single();
 85→
 86→    if (configError) throw new Error(`Config error: ${configError.message}`);
 87→
 88→    if (!config?.outbound_email_enabled) {
 89→      return new Response(JSON.stringify({ error: "Outbound email is disabled", skipped: true }), {
 90→        status: 200,
 91→        headers: { ...corsHeaders, "Content-Type": "application/json" },
 92→      });
 93→    }
 94→
 95→    if (!config.resend_api_key) {
 96→      return new Response(JSON.stringify({ error: "Resend API key not configured" }), {
 97→        status: 400,
 98→        headers: { ...corsHeaders, "Content-Type": "application/json" },
 99→      });
100→    }
101→
102→    // Check per-template notification settings
103→    if (template_key === "ranking_complete" && !config.email_notify_ranking_complete) {
104→      return new Response(JSON.stringify({ skipped: true, reason: "Ranking complete notifications disabled" }), {
105→        status: 200,
106→        headers: { ...corsHeaders, "Content-Type": "application/json" },
107→      });
108→    }
109→    if (template_key === "resume_received" && !config.email_notify_resume_received) {
110→      return new Response(JSON.stringify({ skipped: true, reason: "Resume received notifications disabled" }), {
111→        status: 200,
112→        headers: { ...corsHeaders, "Content-Type": "application/json" },
113→      });
114→    }
115→
116→    // Load template
117→    const { data: template, error: tplError } = await supabase
118→      .from("email_templates")
119→      .select("subject, body_html")
120→      .eq("template_key", template_key)
121→      .single();
122→
123→    if (tplError || !template) {
124→      return new Response(JSON.stringify({ error: `Template '${template_key}' not found` }), {
125→        status: 404,
126→        headers: { ...corsHeaders, "Content-Type": "application/json" },
127→      });
128→    }
129→
130→    // Render template with variables
131→    const subject = renderTemplate(template.subject, variables);
132→    const htmlContent = renderTemplate(template.body_html, variables);
133→
134→    const fromEmail = config.email_from_address || "noreply@rankora.co";
135→    const fromName = config.email_from_name || "Rankora";
136→
137→    // Send via Resend
138→    const result = await sendViaResend(
139→      config.resend_api_key,
140→      { email: fromEmail, name: fromName },
141→      to,
142→      subject,
143→      htmlContent
144→    );
145→
146→    if (!result.ok) {
147→      const friendlyMessage = result.errorMessage || `Resend error (status ${result.status})`;
148→
149→      console.error("Resend error:", result.status, result.body);
150→      await logSystemError({
151→        function_name: "send-email",
152→        error_type: "RESEND_SEND_ERROR",
153→        severity: "warning",
154→        error_message: `Resend error: status=${result.status} body=${result.body}`,
155→      });
156→      return new Response(JSON.stringify({
157→        error: friendlyMessage,
158→      }), {
159→        status: 502,
160→        headers: { ...corsHeaders, "Content-Type": "application/json" },
161→      });
162→    }
163→
164→    return new Response(JSON.stringify({ success: true }), {
165→      status: 200,
166→      headers: { ...corsHeaders, "Content-Type": "application/json" },
167→    });
168→  } catch (err: unknown) {
169→    console.error("send-email error:", err);
170→    await logSystemError({
171→      function_name: "send-email",
172→      error_type: "EMAIL_SEND_ERROR",
173→      severity: "warning",
174→      error_message: errorToMessage(err),
175→      error_stack: errorToStack(err),
176→    });
177→    return new Response(JSON.stringify({ error: err instanceof Error ? err.message : String(err) }), {
178→      status: 500,
179→      headers: { ...corsHeaders, "Content-Type": "application/json" },
180→    });
181→  }
182→});
