 78→function normalizeSkill(skill: string): string {
 79→  // Preserve meaningful symbols: C#, C++, .NET, etc.
 80→  const lower = skill.toLowerCase().trim()
 81→    .replace(/\s+/g, ' ')
 82→    .replace(/[\/\-]/g, ''); // Only strip slashes and hyphens, NOT dots, #, or +
 83→  return synonymToCanonical.get(lower) || synonymToCanonical.get(skill.toLowerCase().trim()) || lower;
 84→}
