 86→function tokenize(term: string): string[] {
 87→  return term.toLowerCase().replace(/[^a-z0-9\s+#]/g, ' ').split(/\s+/).filter(t => t.length > 1);
 88→}
 89→
 90→function tokenOverlap(a: string, b: string): number {
 91→  const tokensA = tokenize(a);
 92→  const tokensB = tokenize(b);
 93→  if (tokensA.length === 0 || tokensB.length === 0) return 0;
 94→  const setB = new Set(tokensB);
 95→  const matched = tokensA.filter(t => setB.has(t)).length;
 96→  return matched / Math.max(tokensA.length, tokensB.length);
 97→}
