 99→function fuzzyMatch(jdTerm: string, resumeTerms: string[]): boolean {
100→  const normalizedJd = normalizeSkill(jdTerm);
101→  for (const rt of resumeTerms) {
102→    const normalizedResume = normalizeSkill(rt);
103→    if (normalizedJd === normalizedResume) return true;
104→    if (normalizedJd.includes(normalizedResume) || normalizedResume.includes(normalizedJd)) return true;
105→    if (tokenOverlap(normalizedJd, normalizedResume) >= 0.5) return true;
106→  }
107→  return false;
108→}
