110→function extractResumeTerms(parsedJson: any): string[] {
111→  const p = parsedJson || {};
112→  const resumeSkills = (p.skills_with_evidence || []).map((s: any) =>
113→    (typeof s === 'string' ? s : s.skill || s.name || '').toLowerCase()
114→  );
115→  const resumeTools = (p.tools || []).map((t: string) => t.toLowerCase());
116→  const domains = p.domain_experience ? [p.domain_experience.toLowerCase()] : [];
117→  const roleTitles = (p.roles_with_dates || []).map((r: any) => (r.title || r.role || '').toLowerCase());
118→  return [...resumeSkills, ...resumeTools, ...domains, ...roleTitles].filter(Boolean);
