136→function mergeSkillSynonyms(adminSynonyms: Record<string, string[]>) {
137→  const merged = { ...SKILL_SYNONYMS };
138→  for (const [canonical, syns] of Object.entries(adminSynonyms)) {
139→    const key = canonical.toLowerCase().trim();
140→    merged[key] = [...new Set([...(merged[key] || []), ...syns.map(s => s.toLowerCase().trim())])];
141→  }
142→  // Rebuild the lookup map
143→  for (const [canonical, syns] of Object.entries(merged)) {
144→    synonymToCanonical.set(canonical, canonical);
145→    for (const syn of syns) synonymToCanonical.set(syn, canonical);
146→  }
147→  return merged;
